export type BrandFillRule = 'nonzero' | 'evenodd';

export type BrandGradientStop = readonly [offset: number, color: string];

export type BrandLinearGradient = {
  readonly kind: 'linear';
  readonly x0: number;
  readonly y0: number;
  readonly x1: number;
  readonly y1: number;
  readonly stops: readonly BrandGradientStop[];
};

export type BrandRadialGradient = {
  readonly kind: 'radial';
  readonly x0: number;
  readonly y0: number;
  readonly r0: number;
  readonly x1: number;
  readonly y1: number;
  readonly r1: number;
  readonly stops: readonly BrandGradientStop[];
};

export type BrandFill = 'currentColor' | string | BrandLinearGradient | BrandRadialGradient;

export type BrandShape =
  | {
      readonly tag: 'path';
      readonly d: string;
      readonly fill: BrandFill;
      readonly fillRule?: BrandFillRule;
      readonly opacity?: number;
    }
  | {
      readonly tag: 'circle';
      readonly cx: number;
      readonly cy: number;
      readonly r: number;
      readonly fill: BrandFill;
      readonly opacity?: number;
    };

export type BrandMark = {
  readonly scale?: number;
  readonly clipPath?: string;
  readonly shapes: readonly BrandShape[];
};

