const EXTERNAL_AGENT_BRANDS: Record<string, ProviderBrandId> = {
  antigravity: 'antigravity',
  'antigravity-acp': 'antigravity',
  claude: 'claude',
  'claude-code': 'claude',
  codex: 'openai',
  'openai-codex': 'openai',
  gemini: 'gemini',
  'gemini-cli': 'gemini',
  opencode: 'opencode',
};

/**
 * Resolves a built-in provider identity to its brand mark, or `null` for
 * custom endpoints, third-party plugins, or providers without a licensed mark.
 */
export function resolveProviderBrand(
  provider?: ProviderBrandIdentity | null,
): ProviderBrandId | null {
  if (!provider) return null;
  if (provider.packageId === 'maka.codex') {
    return provider.name === 'chatgpt' ? 'openai' : null;
  }
  if (provider.packageId === 'maka.providers') {
    return API_PROVIDER_BRANDS[provider.name] ?? null;
  }
  return null;
}

/**
 * Resolves an external agent runtime ID to its brand mark, or `null` when
 * unrecognized so callers fall back cleanly.
 */
export function resolveExternalAgentBrand(runtimeId?: string | null): ProviderBrandId | null {
  if (!runtimeId) return null;
  return EXTERNAL_AGENT_BRANDS[runtimeId.toLowerCase()] ?? null;
}
